CORE111 = [(1,0,2),(2,0,2),(2,1,6),(3,0,2),(3,1,6),(3,2,10),(4,0,2),(4,1,6),(4,2,10),
           (4,3,14),(5,0,2),(5,1,6),(5,2,10),(5,3,14),(6,0,2),(6,1,6)]   # 100 electrons

def cfg(Z, nd, ns, kind):
    """Closed core, then d10 s1 or d9 s2 explicitly.
    The sealed generator ground_occ() is a TABLE that stops at Z=108 -- the seal boundary is
    enforced by the runtime itself. At Z=111 the closed core is written out (100 electrons,
    [Rn] 5f14); 100 + 10 + 1 = 100 + 9 + 2 = 111 either way. No empirical input: the core is
    every shell below 6d, all closed."""
    if Z == 111:
        base = {(n,l):q for n,l,q in CORE111}
    else:
        base = {(n,l):q for n,l,q in ground_occ(Z)}
        for k in [(nd,2),(ns,0)]: base.pop(k, None)
        base = {k:v for k,v in base.items() if v == 2*(2*k[1]+1)}      # closed shells only
    base[(nd,2)] = 10 if kind=='A' else 9
    base[(ns,0)] = 1  if kind=='A' else 2
    return sorted([(n,l,q) for (n,l),q in base.items() if q>0])

